using System;using System.IO;using System.Linq;using System.Text;using System.Net;using System.Net.Sockets;using System.Diagnostics;using System.Threading.Tasks;using System.Collections.Generic;
namespace NcnHelper {
public static class Engine {
 public static string Quote(string s){if(s.Contains("\r")||s.Contains("\n"))throw new Exception("Invalid argument.");var b=new StringBuilder("\"");int n=0;foreach(char c in s){if(c=='\\'){n++;continue;}if(c=='"'){b.Append('\\',n*2+1);b.Append('"');}else{b.Append('\\',n);b.Append(c);}n=0;}b.Append('\\',n*2);b.Append('"');return b.ToString();}
 public static void ModelReady(){var d=Json.Read(Core.Net("http://127.0.0.1:17862/v1/models",null,2));object val;if(!d.TryGetValue("data",out val)||!((System.Collections.IEnumerable)val).Cast<object>().Any(x=>Json.Str((Dictionary<string,object>)x,"id")=="nightcitynet-local"))throw new Exception("Model is not ready yet.");}
 public static async Task<Process> Start(string model,string exe,string context,string layers,Action<string> log){Core.ModelFile(model,true);if(!File.Exists(exe)||!String.Equals(Path.GetFileName(exe),"llama-server.exe",StringComparison.OrdinalIgnoreCase))throw new Exception("Choose the folder containing llama-server.exe and its matching DLLs.");var listener=new TcpListener(IPAddress.Loopback,17862);try{listener.Start();}catch{throw new Exception("Port 17862 is already occupied. No unrelated process will be stopped.");}finally{listener.Stop();}
 string args="--model "+Quote(model)+" --alias nightcitynet-local --host 127.0.0.1 --port 17862 --ctx-size "+(Int32.Parse(context)*2)+" --parallel 2 --n-gpu-layers "+layers+" --batch-size 512 --ubatch-size 256 --offline --no-webui --jinja --reasoning-format deepseek --chat-template-kwargs "+Quote("{\"enable_thinking\":false}");
 var psi=new ProcessStartInfo(exe,args){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true,RedirectStandardOutput=true,WorkingDirectory=Path.GetDirectoryName(exe)};foreach(string key in new[]{"OPENAI_API_KEY","INWORLD_API_KEY","LLAMA_API_KEY","LLAMA_ARG_API_KEY"})psi.EnvironmentVariables.Remove(key);
 var proc=new Process{StartInfo=psi};string error="";proc.ErrorDataReceived+=(s,e)=>{if(e.Data!=null)error=e.Data;};proc.OutputDataReceived+=(s,e)=>{};try{proc.Start();proc.BeginErrorReadLine();proc.BeginOutputReadLine();log("Loading local model...");DateTime limit=DateTime.UtcNow.AddMinutes(3);int step=0;while(DateTime.UtcNow<limit){await Task.Delay(1500).ConfigureAwait(false);if(proc.HasExited)throw new Exception("Runtime exited: "+error);try{ModelReady();log("LLM ready on localhost:17862.");return proc;}catch{}if(++step%10==0)log("Model is still loading...");}throw new Exception("Loading took more than three minutes. Try a smaller model or CPU.");}catch{Stop(proc);throw;}}
 public static void Stop(Process p){if(p==null)return;try{if(!p.HasExited){p.Kill();p.WaitForExit(10000);}}finally{p.Dispose();}}
 public static async Task Check(string model,string exe,string report){Process p=null;var rows=new List<Dictionary<string,object>>();try{p=await Start(model,exe,"16384","12",s=>File.AppendAllText(report+".progress.txt",s+Environment.NewLine)).ConfigureAwait(false);foreach(string language in new[]{"English","Ukrainian"}){var clock=Stopwatch.StartNew();string body=Json.Write(new Dictionary<string,object>{{"model","nightcitynet-local"},{"messages",new[]{new Dictionary<string,object>{{"role","system"},{"content","You are a fictional Night City resident in a game. Speak one short sentence in "+language+". Your reply must start with [EMOTION: neutral] and end with [ACTION: None]. Do not narrate thoughts."}},new Dictionary<string,object>{{"role","user"},{"content","Tell V it is time to go home."}}}},{"max_tokens",120},{"stream",false},{"temperature",0.2}});var d=Json.Read(Core.Net("http://127.0.0.1:17862/v1/chat/completions",body,120));var first=((System.Collections.IEnumerable)d["choices"]).Cast<object>().First();string answer=Json.Str(Json.Obj((Dictionary<string,object>)first,"message"),"content");rows.Add(new Dictionary<string,object>{{"language",language},{"answer",answer},{"elapsed_ms",clock.ElapsedMilliseconds}});if(!answer.StartsWith("[EMOTION: neutral]")||!answer.Contains("[ACTION: None]")||answer.Contains("<think>"))throw new Exception("The model did not preserve the required tags in the short test.");}File.WriteAllText(report,Json.Write(new Dictionary<string,object>{{"model",Path.GetFileName(model)},{"gpu_layers",12},{"context",16384},{"results",rows},{"scope","Direct localhost API only; no game, microphone or cloud calls."}}),new UTF8Encoding(false));}finally{Stop(p);}}
}
}
